Windows


Code
n_win &lt;- nrow(windows)



Windows: 25, each 1 km long by 4 km wide (the last is 0.99 km)
Area covered: 99.9 of 112.5 km². The round end caps beyond the endpoints are not part of any window.
Window 1 is at the Richmond end. Distance along the transect (u, km) is measured from the Richmond endpoint; transect_position() in R/functions.R returns u, the signed lateral offset v, and the window id for any point.



Code
to_ll &lt;- function(x) st_transform(x, 4326)
pal &lt;- colorNumeric("Reds", domain = c(0, 100))

leaflet() |&gt;
  addProviderTiles(providers$Esri.WorldImagery, group = "Imagery") |&gt;
  addProviderTiles(providers$CartoDB.Positron, group = "Light") |&gt;
  addPolygons(data = to_ll(windows), color = "white", weight = 1,
              fillColor = ~pal(imperv_mean), fillOpacity = 0.6,
              label = ~sprintf("Window %d (%.1f km): %.0f%% impervious, %.0f%% forest",
                               window, u_mid_km, imperv_mean, forest_pct),
              group = "Windows") |&gt;
  addPolylines(data = to_ll(line), color = "black", dashArray = "6", weight = 2) |&gt;
  addLegend(pal = pal, values = c(0, 100), title = "Mean impervious (%)") |&gt;
  addLayersControl(baseGroups = c("Light", "Imagery"), overlayGroups = "Windows")

Study area


Code
len_km  &lt;- as.numeric(line$length_km)
area_km &lt;- as.numeric(aoi$area_km2)



Start: Industrial Richmond (37.584817° N, 77.472433° W)
End: Pocahontas State Park (37.373768° N, 77.570813° W)
Transect length: 24.99 km
Buffer: 2 km each side, round end caps
Study area: 112.5 km²
CRS: EPSG:2925 (NAD83(HARN) / Virginia South (ftUS))



Code
to_ll &lt;- function(x) st_transform(x, 4326)
pal &lt;- colorFactor(unname(state_cols), levels = names(state_cols))

leaflet() |&gt;
  addProviderTiles(providers$Esri.WorldImagery, group = "Imagery") |&gt;
  addProviderTiles(providers$CartoDB.Positron, group = "Light") |&gt;
  addPolygons(data = to_ll(tiles), color = "white", weight = 1,
              fillColor = ~pal(state), fillOpacity = 0.4,
              label = ~paste0(tile_name, " (", state, ")"), group = "Tiles") |&gt;
  addPolygons(data = to_ll(aoi), color = "black", weight = 2, fill = FALSE, group = "Study area") |&gt;
  addPolylines(data = to_ll(line), color = "black", dashArray = "6", weight = 2) |&gt;
  addCircleMarkers(data = to_ll(pts), radius = 5, color = "black", label = ~name) |&gt;
  addLegend(pal = pal, values = names(state_cols), title = "Tile status") |&gt;
  addLayersControl(baseGroups = c("Imagery", "Light"), overlayGroups = c("Tiles", "Study area"))
